def calc(expr: str) -> int | str:
    s = expr
    n = len(s)
    i = 0

    def skip() -> None:
        nonlocal i
        while i < n and s[i] == " ":
            i += 1

    def trunc_div(a: int, b: int) -> int:
        if b == 0:
            raise ZeroDivisionError
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def parse_expr() -> int:
        v = parse_term()
        while True:
            skip()
            if i >= n or s[i] not in "+-":
                return v
            op = s[i]
            i += 1
            r = parse_term()
            v = v + r if op == "+" else v - r

    def parse_term() -> int:
        v = parse_factor()
        while True:
            skip()
            if i >= n or s[i] not in "*/%":
                return v
            op = s[i]
            i += 1
            r = parse_factor()
            if op == "*":
                v = v * r
            else:
                q = trunc_div(v, r)
                v = q if op == "/" else v - r * q

    def parse_factor() -> int:
        skip()
        if i < n and s[i] == "-":
            i += 1
            return -parse_factor()
        return parse_power()

    def parse_power() -> int:
        v = parse_primary()
        skip()
        if i >= n or s[i] != "^":
            return v
        i += 1
        e = parse_factor()
        if e < 0:
            raise ValueError
        return v ** e

    def parse_primary() -> int:
        skip()
        if s[i] == "(":
            i += 1
            v = parse_expr()
            skip()
            i += 1  # ')'
            return v
        start = i
        while i < n and s[i].isdigit():
            i += 1
        return int(s[start:i])

    try:
        return parse_expr()
    except (ZeroDivisionError, ValueError):
        return "error"
